/* Bài 3 · Mười một chức năng MESA và bốn mảng vận hành ISA-95 (MS01.03) — sinh bởi tools/author/mes/m03.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l3"),{id:"l3",scenarios:[{"label": "Ví dụ: Phân loại năm yêu cầu", "note": "Mỗi yêu cầu của trưởng xưởng thuộc một chức năng MESA.", "steps": [{"t": "Năm yêu cầu của trưởng xưởng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu của xưởng<\/th><th scope=\"col\">Chức năng MESA<\/th><\/tr><\/thead><tbody><tr><td>Biết máy M2 đang chạy, dừng hay chờ<\/td><td>?<\/td><\/tr><tr><td>Xếp thứ tự lệnh cho ngày mai<\/td><td>?<\/td><\/tr><tr><td>Đưa lệnh xuống trạm khi trạm sẵn sàng<\/td><td>?<\/td><\/tr><tr><td>Hộp lỗi bị chặn lại ở M3<\/td><td>?<\/td><\/tr><tr><td>Tính OEE cuối ca<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Biết máy M2 đang chạy, dừng hay chờ → Quản lý tài nguyên và trạng thái", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu của xưởng<\/th><th scope=\"col\">Chức năng MESA<\/th><\/tr><\/thead><tbody><tr><td>Biết máy M2 đang chạy, dừng hay chờ<\/td><td class=\"new\">Quản lý tài nguyên và trạng thái<\/td><\/tr><tr><td>Xếp thứ tự lệnh cho ngày mai<\/td><td>?<\/td><\/tr><tr><td>Đưa lệnh xuống trạm khi trạm sẵn sàng<\/td><td>?<\/td><\/tr><tr><td>Hộp lỗi bị chặn lại ở M3<\/td><td>?<\/td><\/tr><tr><td>Tính OEE cuối ca<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Xếp thứ tự lệnh cho ngày mai → Lập lịch chi tiết", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu của xưởng<\/th><th scope=\"col\">Chức năng MESA<\/th><\/tr><\/thead><tbody><tr><td>Biết máy M2 đang chạy, dừng hay chờ<\/td><td>Quản lý tài nguyên và trạng thái<\/td><\/tr><tr><td>Xếp thứ tự lệnh cho ngày mai<\/td><td class=\"new\">Lập lịch chi tiết<\/td><\/tr><tr><td>Đưa lệnh xuống trạm khi trạm sẵn sàng<\/td><td>?<\/td><\/tr><tr><td>Hộp lỗi bị chặn lại ở M3<\/td><td>?<\/td><\/tr><tr><td>Tính OEE cuối ca<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Đưa lệnh xuống trạm khi trạm sẵn sàng → Điều phối đơn vị sản xuất", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu của xưởng<\/th><th scope=\"col\">Chức năng MESA<\/th><\/tr><\/thead><tbody><tr><td>Biết máy M2 đang chạy, dừng hay chờ<\/td><td>Quản lý tài nguyên và trạng thái<\/td><\/tr><tr><td>Xếp thứ tự lệnh cho ngày mai<\/td><td>Lập lịch chi tiết<\/td><\/tr><tr><td>Đưa lệnh xuống trạm khi trạm sẵn sàng<\/td><td class=\"new\">Điều phối đơn vị sản xuất<\/td><\/tr><tr><td>Hộp lỗi bị chặn lại ở M3<\/td><td>?<\/td><\/tr><tr><td>Tính OEE cuối ca<\/td><td>?<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "“Đưa lệnh xuống trạm khi trạm sẵn sàng” thuộc chức năng nào?", "o": ["Lập lịch chi tiết", "Điều phối đơn vị sản xuất", "Quản lý quy trình"], "a": 1}, "say": "<p>Lập lịch quyết định <b>thứ tự và thời điểm dự kiến<\/b>; điều phối là <b>phát lệnh thật<\/b> xuống trạm và xử lý khi thực tế khác kế hoạch.<\/p>"}, {"t": "Hộp lỗi bị chặn lại ở M3 → Quản lý chất lượng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu của xưởng<\/th><th scope=\"col\">Chức năng MESA<\/th><\/tr><\/thead><tbody><tr><td>Biết máy M2 đang chạy, dừng hay chờ<\/td><td>Quản lý tài nguyên và trạng thái<\/td><\/tr><tr><td>Xếp thứ tự lệnh cho ngày mai<\/td><td>Lập lịch chi tiết<\/td><\/tr><tr><td>Đưa lệnh xuống trạm khi trạm sẵn sàng<\/td><td>Điều phối đơn vị sản xuất<\/td><\/tr><tr><td>Hộp lỗi bị chặn lại ở M3<\/td><td class=\"new\">Quản lý chất lượng<\/td><\/tr><tr><td>Tính OEE cuối ca<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Tính OEE cuối ca → Phân tích hiệu suất", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu của xưởng<\/th><th scope=\"col\">Chức năng MESA<\/th><\/tr><\/thead><tbody><tr><td>Biết máy M2 đang chạy, dừng hay chờ<\/td><td>Quản lý tài nguyên và trạng thái<\/td><\/tr><tr><td>Xếp thứ tự lệnh cho ngày mai<\/td><td>Lập lịch chi tiết<\/td><\/tr><tr><td>Đưa lệnh xuống trạm khi trạm sẵn sàng<\/td><td>Điều phối đơn vị sản xuất<\/td><\/tr><tr><td>Hộp lỗi bị chặn lại ở M3<\/td><td>Quản lý chất lượng<\/td><\/tr><tr><td>Tính OEE cuối ca<\/td><td class=\"new\">Phân tích hiệu suất<\/td><\/tr><\/tbody><\/table>"}]}, {"label": "Ví dụ: Một hộp lỗi chạm bốn chức năng", "note": "Các chức năng dùng chung dữ liệu của cùng một sự kiện.", "steps": [{"t": "M3 loại một hộp thiếu khối lượng", "html": "<p class=\"mt-calc\">Sự kiện: hộp 487 g bị đẩy ra máng lỗi lúc 09:12 (giả định)<\/p>"}, {"t": "Chức năng 1: Thu thập dữ liệu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chức năng<\/th><th scope=\"col\">Việc làm với sự kiện này<\/th><\/tr><\/thead><tbody><tr><td class=\"new\">Thu thập dữ liệu<\/td><td>Đọc D104 tăng thêm 1 hộp lỗi<\/td><\/tr><\/tbody><\/table>"}, {"t": "Chức năng 2: Quản lý chất lượng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chức năng<\/th><th scope=\"col\">Việc làm với sự kiện này<\/th><\/tr><\/thead><tbody><tr><td>Thu thập dữ liệu<\/td><td>Đọc D104 tăng thêm 1 hộp lỗi<\/td><\/tr><tr><td class=\"new\">Quản lý chất lượng<\/td><td>Ghi kết quả cân: 487 g, dưới giới hạn 495 g<\/td><\/tr><\/tbody><\/table>"}, {"t": "Chức năng 3: Theo dõi sản phẩm và phả hệ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chức năng<\/th><th scope=\"col\">Việc làm với sự kiện này<\/th><\/tr><\/thead><tbody><tr><td>Thu thập dữ liệu<\/td><td>Đọc D104 tăng thêm 1 hộp lỗi<\/td><\/tr><tr><td>Quản lý chất lượng<\/td><td>Ghi kết quả cân: 487 g, dưới giới hạn 495 g<\/td><\/tr><tr><td class=\"new\">Theo dõi sản phẩm và phả hệ<\/td><td>Gắn hộp lỗi với lô hạt LOT-1108<\/td><\/tr><\/tbody><\/table>"}, {"t": "Chức năng 4: Phân tích hiệu suất", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chức năng<\/th><th scope=\"col\">Việc làm với sự kiện này<\/th><\/tr><\/thead><tbody><tr><td>Thu thập dữ liệu<\/td><td>Đọc D104 tăng thêm 1 hộp lỗi<\/td><\/tr><tr><td>Quản lý chất lượng<\/td><td>Ghi kết quả cân: 487 g, dưới giới hạn 495 g<\/td><\/tr><tr><td>Theo dõi sản phẩm và phả hệ<\/td><td>Gắn hộp lỗi với lô hạt LOT-1108<\/td><\/tr><tr><td class=\"new\">Phân tích hiệu suất<\/td><td>Giảm Q của OEE ca 1<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Một hộp lỗi chạm tới bao nhiêu chức năng MESA trong ví dụ này?", "o": ["1", "2", "4"], "a": 2}, "say": "<p>Các chức năng không phải 11 phần mềm riêng. Chúng dùng chung dữ liệu; vì vậy thiết kế dữ liệu (Chương 4) quan trọng hơn danh sách tính năng.<\/p>"}]}, {"label": "Ví dụ: 11 chức năng vào 4 mảng ISA-95", "note": "Đếm số chức năng của từng mảng.", "steps": [{"t": "Bốn mảng của ISA-95 Part 3", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Sản xuất<\/b><small>production<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">·<\/span><div class=\"mt-box\"><b>Chất lượng<\/b><small>quality<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">·<\/span><div class=\"mt-box\"><b>Bảo trì<\/b><small>maintenance<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">·<\/span><div class=\"mt-box\"><b>Kho<\/b><small>inventory<\/small><\/div><\/div>"}, {"t": "Xếp 11 chức năng vào bốn mảng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chức năng MESA<\/th><th scope=\"col\">Mảng ISA-95<\/th><\/tr><\/thead><tbody><tr><td>Quản lý tài nguyên và trạng thái<\/td><td>Sản xuất<\/td><\/tr><tr><td>Lập lịch chi tiết<\/td><td>Sản xuất<\/td><\/tr><tr><td>Điều phối đơn vị sản xuất<\/td><td>Sản xuất<\/td><\/tr><tr><td>Quản lý tài liệu<\/td><td>Sản xuất<\/td><\/tr><tr><td>Thu thập dữ liệu<\/td><td>Sản xuất<\/td><\/tr><tr><td>Quản lý nhân lực<\/td><td>Sản xuất<\/td><\/tr><tr><td>Quản lý chất lượng<\/td><td class=\"hi\">Chất lượng<\/td><\/tr><tr><td>Quản lý quy trình<\/td><td>Sản xuất<\/td><\/tr><tr><td>Quản lý bảo trì<\/td><td class=\"hi\">Bảo trì<\/td><\/tr><tr><td>Theo dõi sản phẩm và phả hệ<\/td><td class=\"hi\">Sản xuất, Kho<\/td><\/tr><tr><td>Phân tích hiệu suất<\/td><td>Sản xuất<\/td><\/tr><\/tbody><\/table>"}, {"t": "Mảng Sản xuất chứa nhiều chức năng nhất", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Mảng<\/th><th scope=\"col\">Số chức năng MESA chạm tới<\/th><\/tr><\/thead><tbody><tr><td>Sản xuất<\/td><td>9<\/td><\/tr><tr><td>Chất lượng<\/td><td>1<\/td><\/tr><tr><td>Bảo trì<\/td><td>1<\/td><\/tr><tr><td>Kho<\/td><td>1<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Theo bảng, bao nhiêu chức năng MESA thuộc mảng Sản xuất?", "o": ["4", "9", "11"], "a": 1}, "say": "<p>ISA-95 Part 3 không xóa bỏ MESA-11, mà gom các hoạt động theo bốn mảng và mô tả mỗi mảng bằng cùng một khuôn: định nghĩa, lập lịch, điều phối, thực hiện, thu thập dữ liệu, theo dõi, phân tích. Khóa này dùng MESA-11 để phân loại nhanh và ISA-95 để thiết kế dữ liệu.<\/p>"}]}, {"label": "Ví dụ: Chọn chức năng cho giai đoạn 1", "note": "Xét giá trị ngay và phụ thuộc giữa các chức năng.", "steps": [{"t": "Xưởng chỉ đủ nguồn lực cho 3 chức năng đầu tiên", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chức năng<\/th><th scope=\"col\">Giá trị ngay<\/th><th scope=\"col\">Phụ thuộc<\/th><\/tr><\/thead><tbody><tr><td>Thu thập dữ liệu<\/td><td>Cao<\/td><td>Không<\/td><\/tr><tr><td>Phân tích hiệu suất (OEE)<\/td><td>Cao<\/td><td>Thu thập dữ liệu<\/td><\/tr><tr><td>Điều phối lệnh<\/td><td>Trung bình<\/td><td>Thu thập dữ liệu<\/td><\/tr><tr><td>Lập lịch chi tiết<\/td><td>Trung bình<\/td><td>Điều phối, dữ liệu năng lực<\/td><\/tr><\/tbody><\/table>"}, {"t": "Chọn: thu thập dữ liệu, OEE, điều phối", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Giai đoạn<\/th><th scope=\"col\">Chức năng<\/th><th scope=\"col\">Chương<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td class=\"ok\">Thu thập dữ liệu<\/td><td>12<\/td><\/tr><tr><td>1<\/td><td class=\"ok\">Phân tích hiệu suất<\/td><td>13–14<\/td><\/tr><tr><td>1<\/td><td class=\"ok\">Điều phối lệnh<\/td><td>15<\/td><\/tr><tr><td>2<\/td><td>Chất lượng, truy xuất, bảo trì<\/td><td>16–19<\/td><\/tr><tr><td>3<\/td><td>Lập lịch chi tiết<\/td><td>22<\/td><\/tr><\/tbody><\/table>", "say": "<p>Thu thập dữ liệu là nền của mọi chức năng khác. Lập lịch chi tiết cần dữ liệu năng lực thật nên làm sau cùng. Thứ tự các chương của khóa đi theo đúng logic này.<\/p>"}]}, {"label": "Bẫy: Nhầm lập lịch với điều phối", "note": "Máy hỏng giữa ca: ai đổi lệnh, theo chức năng nào?", "steps": [{"t": "Kế hoạch lúc 06:00", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Máy<\/th><th scope=\"col\">Lệnh 1<\/th><th scope=\"col\">Lệnh 2<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td>WO-0412 (06:00–10:00)<\/td><td>WO-0413 (10:30–14:00)<\/td><\/tr><\/tbody><\/table>", "say": "<p>Đây là kết quả của <b>lập lịch<\/b>.<\/p>"}, {"t": "08:15 · M1 hỏng, dự kiến sửa 1 giờ", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Máy<\/th><th scope=\"col\">Lệnh 1<\/th><th scope=\"col\">Lệnh 2<\/th><\/tr><\/thead><tbody><tr><td>M1<\/td><td class=\"bad\">WO-0412 <b>tạm dừng<\/b><\/td><td>WO-0413 chờ<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Quyết định phát WO-0413 sang máy dự phòng ngay bây giờ thuộc chức năng nào?", "o": ["Lập lịch chi tiết", "Điều phối đơn vị sản xuất", "Quản lý bảo trì"], "a": 1}}, {"t": "Điều phối xử lý thực tế lệch kế hoạch", "html": "<p class=\"mt-calc\">Điều phối = phát lệnh thật và phản ứng khi thực tế khác lịch<\/p>", "say": "<p>Nhầm hai chức năng này dẫn tới thiết kế sai: một bộ lập lịch đẹp nhưng không ai cập nhật khi máy hỏng.<\/p>"}]}, {"label": "Lỗi: Đưa MRP vào yêu cầu MES", "note": "Tính nhu cầu vật tư cả tháng là việc của ERP.", "steps": [{"t": "Một bản yêu cầu MES ghi", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu<\/th><th scope=\"col\">Chức năng<\/th><\/tr><\/thead><tbody><tr><td>Tính nhu cầu hạt điều cho tháng 12 theo đơn hàng<\/td><td class=\"bad\">Quản lý tài nguyên?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Đây là hoạch định nhu cầu vật tư (MRP)", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Yêu cầu<\/th><th scope=\"col\">Hệ thống<\/th><\/tr><\/thead><tbody><tr><td>Tính nhu cầu hạt điều cho tháng 12<\/td><td class=\"ok\">ERP (MRP)<\/td><\/tr><tr><td>Cấp đúng lô hạt cho lệnh đang chạy<\/td><td class=\"ok\">MES<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Tính nhu cầu vật tư cho cả tháng là việc của hệ thống nào?", "o": ["MES", "ERP", "PLC"], "a": 1}, "say": "<p>Khung thời gian tháng và dữ liệu đơn hàng thuộc cấp 4. MES chỉ lo vật tư <b>tại chuyền, cho lệnh đang chạy<\/b>.<\/p>"}]}, {"label": "Bẫy: Quản lý nhân lực là tính lương", "note": "MES biết ai ở trạm nào trong ca; lương thuộc phần mềm khác.", "steps": [{"t": "“MES quản lý nhân lực” nghĩa là gì?", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Việc<\/th><th scope=\"col\">Thuộc MES?<\/th><\/tr><\/thead><tbody><tr><td>Ai đang vận hành máy M1, có chứng chỉ không<\/td><td>?<\/td><\/tr><tr><td>Tính lương tháng, bảo hiểm<\/td><td>?<\/td><\/tr><\/tbody><\/table>"}, {"t": "Tách hai loại việc", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Việc<\/th><th scope=\"col\">Thuộc MES?<\/th><\/tr><\/thead><tbody><tr><td>Ai đang vận hành máy M1, có chứng chỉ không<\/td><td class=\"ok\">Có<\/td><\/tr><tr><td>Tính lương tháng, bảo hiểm<\/td><td class=\"bad\">Không (phần mềm nhân sự, ERP)<\/td><\/tr><\/tbody><\/table>", "say": "<p>Quản lý nhân lực trong MES là người nào, ở trạm nào, đủ điều kiện không, <b>trong ca<\/b>. MES có thể gửi giờ công cho phần mềm nhân sự, nhưng không tính lương.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l3"),"l3",[{"kind": "pick", "t": "Yêu cầu thuộc chức năng nào?", "d": "<p>Chọn chức năng MESA phù hợp nhất cho mỗi yêu cầu.<\/p>", "cats": ["Thu thập dữ liệu", "Lập lịch chi tiết", "Điều phối đơn vị sản xuất", "Quản lý chất lượng", "Quản lý bảo trì", "Theo dõi sản phẩm và phả hệ"], "items": [{"q": "Đọc số đếm của 3 FX5U mỗi giây", "a": 0}, {"q": "Xếp 6 lệnh của ngày mai lên 3 máy để ít đổi khuôn nhất", "a": 1}, {"q": "M1 hỏng, chuyển lệnh đang chờ sang máy dự phòng", "a": 2}, {"q": "Chặn lô hộp có khối lượng trung bình vượt giới hạn", "a": 3}, {"q": "Nhắc thay dao cắt màng sau 200 000 chu kỳ", "a": 4}, {"q": "Tìm mọi hộp dùng lô hạt LOT-1108", "a": 5}], "hints": ["Từ khóa “xếp”, “ngày mai” gợi ý lập lịch; “chuyển ngay”, “máy hỏng” gợi ý điều phối.", "Dao cắt sau một số chu kỳ là bảo trì; “mọi hộp dùng lô” là truy xuất phả hệ.", "Đọc số đếm từ PLC là thu thập dữ liệu."], "why": "Đọc PLC: thu thập dữ liệu. Xếp lệnh ngày mai: lập lịch. Chuyển lệnh khi máy hỏng: điều phối. Chặn lô vượt giới hạn: chất lượng. Thay dao theo chu kỳ: bảo trì. Tìm hộp theo lô: phả hệ."}, {"kind": "pick", "t": "Thuộc mảng ISA-95 nào?", "d": "<p>Chọn mảng vận hành ISA-95 Part 3 cho mỗi hoạt động.<\/p>", "cats": ["Sản xuất", "Chất lượng", "Bảo trì", "Kho"], "items": [{"q": "Phát lệnh WO-0412 xuống máy M1", "a": 0}, {"q": "Ghi kết quả cân kiểm tra của 50 hộp mẫu", "a": 1}, {"q": "Lập phiếu sửa chữa khi M2 báo lỗi 12", "a": 2}, {"q": "Chuyển 120 kg hạt từ kho lên khu chờ của dây chuyền", "a": 3}, {"q": "Tính OEE của ca 1", "a": 0}, {"q": "Lên lịch kiểm định cân định lượng hằng năm", "a": 2}], "hints": ["Chất lượng: kiểm tra, đo, đánh giá sản phẩm.", "Bảo trì: sửa chữa, kiểm định, thay thế thiết bị.", "Kho: di chuyển và theo dõi vật tư; còn lại phần lớn là sản xuất."], "why": "Phát lệnh và OEE thuộc vận hành sản xuất; cân kiểm tra thuộc chất lượng; sửa chữa và kiểm định cân thuộc bảo trì; chuyển vật tư thuộc kho."}, {"kind": "pick", "t": "MES, ERP hay trao đổi giữa hai bên?", "d": "<p>Chọn hệ thống thực hiện, hoặc chọn “Trao đổi” nếu dữ liệu do một bên tạo và bên kia cần nhận.<\/p>", "cats": ["ERP", "MES", "Trao đổi giữa ERP và MES"], "items": [{"q": "Tính giá thành kế hoạch của hộp 500 g", "a": 0}, {"q": "Ghi thời điểm bắt đầu, kết thúc từng lần dừng máy", "a": 1}, {"q": "Hoạch định nhu cầu vật tư (MRP) của tháng 12", "a": 0}, {"q": "Sản lượng thực tế và tiêu hao vật tư của lệnh WO-0412", "a": 2}, {"q": "Kiểm tra công nhân có chứng chỉ vận hành máy M1 trước khi đăng nhập", "a": 1}, {"q": "Đơn hàng cần sản xuất của tuần tới", "a": 2}], "hints": ["Khung thời gian tháng, tài chính, đơn hàng của khách: ERP.", "Việc trong ca, tại trạm, theo sự kiện máy: MES.", "Đơn hàng đi từ ERP xuống MES; sản lượng thực tế đi từ MES lên ERP: cả hai đều là trao đổi."], "why": "Giá thành và MRP là việc của ERP. Ghi dừng máy và kiểm tra chứng chỉ tại trạm là việc của MES. Đơn hàng (ERP → MES) và sản lượng, tiêu hao thực tế (MES → ERP) là dữ liệu trao đổi qua giao diện ISA-95."}]);

makeQuiz("quiz3","score3",[{"q": "Máy M1 hỏng lúc 08:15, trưởng ca chuyển lệnh đang chờ sang máy dự phòng. Đây là chức năng nào?", "o": ["Lập lịch chi tiết", "Quản lý bảo trì", "Phân tích hiệu suất", "Điều phối đơn vị sản xuất"], "a": 3, "e": "Điều phối phát lệnh thật và xử lý khi thực tế lệch lịch. Lập lịch là kế hoạch dự kiến được làm trước."}, {"q": "Vì sao các dự án MES thường làm thu thập dữ liệu trước tiên?", "o": ["Vì đó là chức năng rẻ nhất", "Vì mọi chức năng khác đều cần dữ liệu từ máy", "Vì ISA-95 bắt buộc như vậy", "Vì ERP yêu cầu"], "a": 1, "e": "OEE, điều phối, truy xuất, bảo trì theo chu kỳ đều dùng dữ liệu thu thập từ máy. Thiếu nền này, các chức năng khác chạy trên số liệu nhập tay."}, {"q": "Câu nào nói đúng về quản lý nhân lực trong MES?", "o": ["MES biết ai đang ở trạm nào và có đủ điều kiện vận hành không", "MES tính lương tháng cho công nhân", "MES tuyển dụng công nhân mới", "MES không liên quan tới con người"], "a": 0, "e": "Quản lý nhân lực trong MES là trạng thái và năng lực của người trong ca. Lương, tuyển dụng thuộc phần mềm nhân sự hoặc ERP."}, {"q": "Bốn mảng vận hành của ISA-95 Part 3 là gì?", "o": ["Kế hoạch, mua hàng, bán hàng, tài chính", "PLC, HMI, SCADA, MES", "Sản xuất, chất lượng, bảo trì, kho", "Thu thập, lưu trữ, hiển thị, báo cáo"], "a": 2, "e": "ISA-95 Part 3 mô tả quản lý vận hành sản xuất, chất lượng, bảo trì và kho. Phương án đầu là các mảng của ERP."}, {"q": "Một hộp bị M3 loại vì thiếu khối lượng. Chức năng nào KHÔNG tham gia trong ví dụ của bài?", "o": ["Thu thập dữ liệu", "Quản lý chất lượng", "Theo dõi sản phẩm và phả hệ", "Lập lịch chi tiết"], "a": 3, "e": "Sự kiện hộp lỗi được thu thập, ghi kết quả chất lượng, gắn với lô và làm giảm Q của OEE. Lập lịch chi tiết không xử lý sự kiện này."}]);

